import{_ as l,o as i,c as s,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-12-18","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-12-18","date":"2024-12-18T00:00:00.000Z","updated":"2024-12-18T00:00:00.000Z","tags":["Ceph","RGW","S3接口","特性跟踪","安全令牌服务"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-18.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-18.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-12-18.md"};function a(r,e,n,g,d,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要-ceph-开发会议" tabindex="-1">会议纪要 - Ceph 开发会议 <a class="header-anchor" href="#会议纪要-ceph-开发会议" aria-label="Permalink to &quot;会议纪要 - Ceph 开发会议&quot;">​</a></h3><p><strong>日期</strong>: 2023年某月某日<br><strong>主持人</strong>: 未提及<br><strong>参会人员</strong>: Jesse, Joseph, Alex, Radislav, Casey, 及其他Ceph开发人员</p><h4 id="_1-joseph的议题-跟踪工作进展及s3接口改进" tabindex="-1">1. <strong>Joseph的议题：跟踪工作进展及S3接口改进</strong> <a class="header-anchor" href="#_1-joseph的议题-跟踪工作进展及s3接口改进" aria-label="Permalink to &quot;1. **Joseph的议题：跟踪工作进展及S3接口改进**&quot;">​</a></h4><ul><li><strong>背景</strong>: Joseph希望了解Ceph社区的活跃工作，特别是S3接口相关的开发进展，以便Bloomberg在2025年规划中提供帮助。</li><li><strong>讨论内容</strong>: <ul><li>Joseph提到在过去的开发者月会上提出了S3用户和开发者的优先事项，最近注意到一些新特性（如merge y）的开发，但不确定如何跟踪这些特性的进展。</li><li>Casey指出，目前没有正式的特性跟踪文档，只有SEF开发者峰会上的一些非正式记录，且没有明确的优先级或截止日期。</li><li>Joseph建议是否可以为Ceph社区建立一个特性跟踪工具，可能通过Redmine或其他类似工具。</li><li>Casey提到Trello之前由Red Hat付费使用，但现已停止，建议可以考虑使用Redmine的敏捷功能或其他工具。</li></ul></li><li><strong>决定事项</strong>: <ul><li>考虑为Ceph社区建立一个特性跟踪工具，可能通过Redmine或其他类似工具。</li><li>每月或每两个月进行一次同步会议，更新特性进展。</li></ul></li></ul><h4 id="_2-jesse的议题-optional-yield的pr" tabindex="-1">2. <strong>Jesse的议题：optional yield的PR</strong> <a class="header-anchor" href="#_2-jesse的议题-optional-yield的pr" aria-label="Permalink to &quot;2. **Jesse的议题：optional yield的PR**&quot;">​</a></h4><ul><li><strong>背景</strong>: Jesse发现Ceph中使用了<code>optional yield</code>，并考虑是否可以用C++的<code>std--optional</code>替代。</li><li><strong>讨论内容</strong>: <ul><li>Jesse进行了性能测试，发现<code>std: -optional</code>与现有实现性能几乎相同，但提供了更多的成员函数和功能。</li><li>讨论了是否需要这些额外功能，以及是否应该关闭相关PR。</li></ul></li><li><strong>决定事项</strong>: <ul><li>如果没有人需要这些额外功能，Jesse将关闭相关PR。</li></ul></li></ul><h4 id="_3-jesse的议题-rgw-admin工具的重构" tabindex="-1">3. <strong>Jesse的议题：RGW Admin工具的重构</strong> <a class="header-anchor" href="#_3-jesse的议题-rgw-admin工具的重构" aria-label="Permalink to &quot;3. **Jesse的议题：RGW Admin工具的重构**&quot;">​</a></h4><ul><li><strong>背景</strong>: Jesse计划对RGW Admin工具进行大量重构，希望将其代码移至单独的目录。</li><li><strong>讨论内容</strong>: <ul><li>Jesse解释了将RGW Admin工具移至单独目录的原因，主要是为了更好地组织代码，避免顶级目录过于杂乱。</li><li>讨论了是否有人依赖当前的文件结构，Jesse表示主要是构建系统需要调整。</li></ul></li><li><strong>决定事项</strong>: <ul><li>同意将RGW Admin工具移至单独目录，Jesse将继续进行重构。</li></ul></li></ul><h4 id="_4-alex的议题-sts-security-token-service-的实现" tabindex="-1">4. <strong>Alex的议题：STS（Security Token Service）的实现</strong> <a class="header-anchor" href="#_4-alex的议题-sts-security-token-service-的实现" aria-label="Permalink to &quot;4. **Alex的议题：STS（Security Token Service）的实现**&quot;">​</a></h4><ul><li><strong>背景</strong>: Alex讨论了Ceph的STS实现，特别是如何处理OIDC和JWT的签名验证。</li><li><strong>讨论内容</strong>: <ul><li>Alex提到AWS的STS实现与RFC标准不完全一致，Ceph是否应该更接近AWS的实现，还是遵循RFC标准。</li><li>讨论了是否可以在Ceph中添加扩展功能，同时提供一个严格兼容AWS的模式。</li></ul></li><li><strong>决定事项</strong>: <ul><li>建议安排一次专门的会议，讨论STS的实现细节，特别是如何平衡AWS兼容性和RFC标准。</li><li>可能邀请Marcus Watts和Sage McTaggart参与讨论。</li></ul></li></ul><h4 id="_5-radislav的议题-rgw的多对象rados事务" tabindex="-1">5. <strong>Radislav的议题：RGW的多对象RADOS事务</strong> <a class="header-anchor" href="#_5-radislav的议题-rgw的多对象rados事务" aria-label="Permalink to &quot;5. **Radislav的议题：RGW的多对象RADOS事务**&quot;">​</a></h4><ul><li><strong>背景</strong>: Radislav正在收集RGW中多对象RADOS事务的需求，特别是在开发者峰会上讨论的相关内容。</li><li><strong>讨论内容</strong>: <ul><li>Radislav希望将所有涉及多对象修改的用例整理到一个文档中，以便进一步讨论。</li><li>讨论了是否需要完全的多对象事务支持，还是可以通过其他方式（如单对象更新+额外操作）实现。</li></ul></li><li><strong>决定事项</strong>: <ul><li>Radislav将把文档移至GitHub的Gist上，方便更多人参与讨论。</li></ul></li></ul><h4 id="_6-其他议题" tabindex="-1">6. <strong>其他议题</strong> <a class="header-anchor" href="#_6-其他议题" aria-label="Permalink to &quot;6. **其他议题**&quot;">​</a></h4><ul><li><strong>Barbican集成</strong>: 讨论了Barbican与Ceph的集成问题，Marcus Watts被认为是相关领域的负责人。</li><li><strong>会议安排</strong>: 决定取消下周的会议，因为圣诞节和新年假期临近。</li></ul><p><strong>下次会议</strong>: 2024年1月（具体时间待定）</p><p><strong>总结</strong>: 本次会议主要讨论了Ceph社区的特性跟踪工具、RGW Admin工具的重构、STS实现的兼容性问题，以及RGW的多对象RADOS事务需求。会议决定将安排专门的会议讨论STS实现，并考虑为Ceph社区建立一个特性跟踪工具。</p>',16)])])}const c=l(o,[["render",a]]);export{u as __pageData,c as default};
